import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { LuUsers, LuArrowLeft } from 'react-icons/lu';
import { getStudent } from '../api/studentApi';
import type { Student } from '../api/studentApi';
import styles from './StudentDetail.module.css';
import PaymentTab from './student-detail/PaymentTab';
import MealTab from './student-detail/MealTab';
import AttendanceTab from './student-detail/AttendanceTab';
import RequestTab from './student-detail/RequestTab';
import StudyTimeTab from './student-detail/StudyTimeTab';
import MeritTab from './student-detail/MeritTab';
import StudentInfoTab from './student-detail/StudentInfoTab';

/* ── Tabs ── */

const TABS = [
  '수납현황',
  '급식 신청내역',
  '출결사항',
  '신청사항',
  '순공시간',
  '상/벌점',
  '학생 정보',
] as const;

type TabKey = (typeof TABS)[number];

/* ── Page ── */

export default function StudentDetail() {
  const { studentId } = useParams<{ studentId: string }>();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<TabKey>('수납현황');

  const [student, setStudent] = useState<Student | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!studentId) return;
    setLoading(true);
    setError('');
    getStudent(Number(studentId))
      .then((data) => setStudent(data))
      .catch(() => setError('학생 정보를 불러오는데 실패했습니다.'))
      .finally(() => setLoading(false));
  }, [studentId]);

  const displayName = student?.name ?? '알 수 없는 학생';
  const displayNumber = student?.studentNumber ?? studentId ?? '';

  const renderTabContent = () => {
    switch (activeTab) {
      case '수납현황':
        return <PaymentTab />;
      case '급식 신청내역':
        return <MealTab studentName={displayName} studentId={displayNumber} />;
      case '출결사항':
        return <AttendanceTab />;
      case '신청사항':
        return <RequestTab />;
      case '순공시간':
        return <StudyTimeTab />;
      case '상/벌점':
        return <MeritTab />;
      case '학생 정보':
        return <StudentInfoTab student={student} />;
    }
  };

  if (loading) {
    return (
      <div className={styles.page}>
        <div style={{ textAlign: 'center', padding: '32px', color: '#9ca3af' }}>불러오는 중...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className={styles.page}>
        <div style={{ textAlign: 'center', padding: '32px', color: '#e74c3c' }}>{error}</div>
      </div>
    );
  }

  return (
    <div className={styles.page}>
      {/* Header */}
      <div className={styles.pageHeader}>
        <button
          className={styles.backButton}
          type="button"
          onClick={() => navigate('/students')}
        >
          <LuArrowLeft />
        </button>
        <LuUsers className={styles.pageHeaderIcon} />
        <h2 className={styles.pageTitle}>
          {displayName} 학생
        </h2>
        <span className={styles.studentId}>({displayNumber})</span>
      </div>

      {/* Tabs */}
      <div className={styles.tabs}>
        {TABS.map((tab) => (
          <button
            key={tab}
            type="button"
            className={`${styles.tab} ${activeTab === tab ? styles.tabActive : ''}`}
            onClick={() => setActiveTab(tab)}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div className={styles.contentCard}>
        {renderTabContent()}
      </div>
    </div>
  );
}
